payload.tools_text:
[
 {
  "name": "create_document",
  "description": "Create a new shader document, then compile it and return the result \u2014 compile errors at their exact line, or that it compiled clean (same feedback as an edit). Leave source empty for a ready-made starter shader you then edit; or pass full GLSL (follow the project shader conventions so it compiles). By default the new document becomes the user's active document (so a follow-up edit with no target lands on it); pass switch_to=false to create it in the background and edit it via the document id this returns. Returns the new document's id and its compile result.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "name": {
     "description": "a display name for the new document",
     "title": "Name",
     "type": "string"
    },
    "example": {
     "default": "",
     "description": "an example: handle from the EXAMPLE LIBRARY to start from (e.g. for a text-rendering shader, pick the text example) \u2014 prefer this over writing source blind; empty = the default blank-canvas starter",
     "title": "Example",
     "type": "string"
    },
    "source": {
     "default": "",
     "description": "initial GLSL source; empty = the chosen example (or the starter), or full GLSL following the project conventions (overrides the example body)",
     "title": "Source",
     "type": "string"
    },
    "switch_to": {
     "default": true,
     "description": "switch the user's view to the new document (true), or create it in the background and keep editing via its returned id (false)",
     "title": "Switch To",
     "type": "boolean"
    }
   },
   "required": [
    "name"
   ],
   "title": "_CreateDocumentArgs",
   "type": "object"
  }
 },
 {
  "name": "delete_document",
  "description": "Delete a shader document. Pass the document id (from the project map) \u2014 required, never empty. This is destructive, so the user is shown a Yes/No confirmation before it happens; if they decline you'll get 'user declined' and should stop and explain. The document moves to the project trash and the user can recover it, so reassure them it's not permanently lost. After a delete the document is gone from the project map; do not read or edit it again.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "document": {
     "description": "document id (from the project map) to delete \u2014 REQUIRED, never empty (deleting is destructive, so the target must be explicit, not the current document)",
     "title": "Document",
     "type": "string"
    }
   },
   "required": [
    "document"
   ],
   "title": "_DeleteDocumentArgs",
   "type": "object"
  }
 },
 {
  "name": "edit_script",
  "description": "THE partial-edit tool for a script \u2014 the mirror of edit_shader, for script.py instead of GLSL. Replace an exact substring (old_str = the region copied VERBATIM from read_script / the working set; new_str = its replacement; empty new_str deletes; non-unique old_str fails \u2014 add context or replace_all=true). For a localized tweak; use write_script for a fresh script or a full rewrite. I re-compile + motion-probe and return the same verdict as write_script.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "old_str": {
     "description": "exact substring of the script.py source to replace (copied VERBATIM from read_script / the working set)",
     "title": "Old Str",
     "type": "string"
    },
    "new_str": {
     "description": "the replacement text (empty deletes the region)",
     "title": "New Str",
     "type": "string"
    },
    "replace_all": {
     "default": false,
     "description": "replace every occurrence (resolves a non-unique old_str)",
     "title": "Replace All",
     "type": "boolean"
    },
    "document": {
     "default": "",
     "description": "document id (from the project map); empty = the document you are currently working on",
     "title": "Document",
     "type": "string"
    }
   },
   "required": [
    "old_str",
    "new_str"
   ],
   "title": "_EditScriptArgs",
   "type": "object"
  }
 },
 {
  "name": "edit_shader",
  "description": "THE partial-edit tool: replace an exact substring of the source, then recompile. Works for any localized change \u2014 a statement, a block, a whole function: old_str is the region to replace, copied VERBATIM from the working set (whitespace-tolerant match); new_str is its replacement. To INSERT, quote a neighbor line as old_str and re-send it plus the new lines in new_str; to DELETE a region, pass an empty new_str. If old_str appears more than once, the edit fails \u2014 add surrounding context to make it unique, or set replace_all=true. To rewrite a whole file (or most of it), use write_shader instead. After the edit I recompile and return any compile errors at the exact line; if there are none, the edit compiled clean. You cannot see the rendered image \u2014 never claim a visual result, only that it compiled.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "old_str": {
     "description": "exact substring of the source to replace",
     "title": "Old Str",
     "type": "string"
    },
    "new_str": {
     "description": "the replacement text",
     "title": "New Str",
     "type": "string"
    },
    "replace_all": {
     "default": false,
     "description": "replace every occurrence (resolves a non-unique old_str)",
     "title": "Replace All",
     "type": "boolean"
    },
    "target": {
     "default": "",
     "description": "what to edit: empty = the shader you're currently working on; a document id (from the project map) = that document; a 'lib:<path>' address (from the library catalogue) = that library file",
     "title": "Target",
     "type": "string"
    }
   },
   "required": [
    "old_str",
    "new_str"
   ],
   "title": "_EditArgs",
   "type": "object"
  }
 },
 {
  "name": "grep",
  "description": "Find where a substring occurs across every shader document and the whole library. Returns origin-labeled file:line hits (a document id, or a lib: address). Use it to LOCATE something (e.g. which shaders use u_time, or where a helper is called); then read_shader / read_lib to read the full thing. Substring match (a comment can match too).",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "query": {
     "description": "substring to find across every document's source and the library",
     "title": "Query",
     "type": "string"
    }
   },
   "required": [
    "query"
   ],
   "title": "_GrepArgs",
   "type": "object"
  }
 },
 {
  "name": "load_tools",
  "description": "Load extra tools you need for THIS turn by name. To keep the toolset lean, the tools below are NOT loaded by default \u2014 call load_tools with their names to make them available for the rest of the turn. Load a tool BEFORE you need to call it. Available:\n- bind_media: bind an image/video to a sampler2D uniform (opens the user's file picker)\n- create_telegram_pack: create + activate a new Telegram sticker pack\n- delete_lib_file: delete a shader-library file (a lib: address) to the trash\n- delete_telegram_pack: delete a Telegram sticker pack (external + irreversible)\n- duplicate_document: fork a document into a variant (copies shader/script/media)\n- import_document: import a .glsl shader file from the user's disk as a new document\n- list_telegram_packs: list the user's saved Telegram sticker packs\n- rename_document: rename a document's display name\n- select_telegram_pack: switch the active Telegram sticker pack\n- set_canvas_size: set a document's render resolution (canvas WxH)\n- set_telegram_token: set the Telegram bot token to connect Telegram\n- set_youtube_credentials: set up YouTube credentials to enable publishing\n- telegram_connect: re-run the Telegram link after the user starts the bot\n- unbind_media: reset a sampler2D uniform to no bound media",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "names": {
     "description": "the lazy tool names to load for the rest of this turn (from the catalogue in this tool's description)",
     "items": {
      "type": "string"
     },
     "title": "Names",
     "type": "array"
    }
   },
   "required": [
    "names"
   ],
   "title": "_LoadToolsArgs",
   "type": "object"
  }
 },
 {
  "name": "probe_render",
  "description": "A read-only MEASUREMENT of a shader's frame at a chosen time `t`: the facts line (ink %, bbox, ink mean color, luma rows, or FLAT \u2014 one uniform color). Use it to check an animated shader past t=0, to re-measure after a set_uniform, and before you state what the frame contains. Unlike render_image (a heavy, gated, file-writing deliverable) it never confirms or writes a file, and it is free. It measures \u2014 it does not SEE: the numbers are all you get, and how the result LOOKS stays the user's judgment.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "document": {
     "default": "",
     "description": "document id (from the project map); empty = the document you're working on",
     "title": "Document",
     "type": "string"
    },
    "t": {
     "default": 0.0,
     "description": "the animation time (seconds) to render at; 0.0 = the export clock the user renders to a file. Aim it at a specific moment to inspect an animated shader past t=0 (e.g. t=2.5 to see the flame mid-rise).",
     "title": "T",
     "type": "number"
    }
   },
   "title": "_ProbeRenderArgs",
   "type": "object"
  }
 },
 {
  "name": "publish_telegram",
  "description": "Render the current shader as a Telegram sticker (3s WebM) and add it to the user's selected sticker pack. EXTERNAL + LIVE \u2014 the user confirms first. Needs Telegram connected + a pack selected \u2014 both of which YOU do (set_telegram_token, create/select_telegram_pack), not the user in Settings. The pack becomes an 'Open in Telegram' button shown to the USER \u2014 you do NOT get the URL.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "emoji": {
     "default": "\ud83c\udfa8",
     "description": "the emoji to associate with the sticker (one character)",
     "title": "Emoji",
     "type": "string"
    }
   },
   "title": "_PublishTelegramArgs",
   "type": "object"
  }
 },
 {
  "name": "publish_youtube",
  "description": "Render the current shader as a video and upload it to the user's YouTube channel (as a private video they publish from Studio). EXTERNAL + LIVE \u2014 the user confirms first. Needs YouTube connected, which YOU do (set_youtube_credentials), not the user in Settings. The upload becomes an 'Open in YouTube' button shown to the USER \u2014 you do NOT get the Studio URL.",
  "parameters": {
   "$defs": {
    "RenderShape": {
     "enum": [
      "native",
      "short_720",
      "short_1080",
      "short_1440",
      "wide_720",
      "wide_1080",
      "wide_1440"
     ],
     "title": "RenderShape",
     "type": "string"
    }
   },
   "additionalProperties": false,
   "properties": {
    "title": {
     "description": "the video title",
     "title": "Title",
     "type": "string"
    },
    "description": {
     "default": "",
     "description": "the video description",
     "title": "Description",
     "type": "string"
    },
    "shape": {
     "$ref": "#/$defs/RenderShape",
     "default": "native",
     "description": "the output shape: a short_* (9:16, <=60s, a YouTube Short) or a wide_*/native (16:9 or canvas, a normal video). output size: native (the document's canvas size, any aspect), short_720/short_1080/short_1440 (9:16 vertical), or wide_720/wide_1080/wide_1440 (16:9). Dims snap to the codec alignment."
    }
   },
   "required": [
    "title"
   ],
   "title": "_PublishYoutubeArgs",
   "type": "object"
  }
 },
 {
  "name": "read_lib",
  "description": "Read the full body of one or more library functions by name (the catalogue in your context lists signatures only). Use this when you need to see how a SB_* helper works before calling it, or to read it before editing it.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "names": {
     "description": "library function names (SB_*) whose full body you want to read",
     "items": {
      "type": "string"
     },
     "title": "Names",
     "type": "array"
    }
   },
   "required": [
    "names"
   ],
   "title": "_ReadLibArgs",
   "type": "object"
  }
 },
 {
  "name": "read_script",
  "description": "Read a document's Python script \u2014 the `update(self, ctx)` that drives uniforms from CPU state. Returns the source line-numbered. A document with NO script yet returns a STUB (its drivable uniforms + their value shapes + an empty `update` to fill in) \u2014 read it, then write_script a real body. Read this before editing a script you did not just write.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "document": {
     "default": "",
     "description": "document id (from the project map); empty = the document you are currently working on",
     "title": "Document",
     "type": "string"
    }
   },
   "title": "_ReadScriptArgs",
   "type": "object"
  }
 },
 {
  "name": "read_shader",
  "description": "Bring shader documents into your WORKING SET \u2014 their full live source (line-numbered), uniforms, and compile errors then appear in the working-set block at the bottom of the conversation, rebuilt every step with CURRENT line numbers. Pass a list of document ids to add several at once (e.g. to compare two shaders); a `lib:` address reads that library file whole the same way; leave documents empty for the document you are currently working on (it is already in your working set). Use this to add a DIFFERENT document before editing it. The document you are currently working on needs no read before you edit it \u2014 its source is already in the working set. You cannot see the rendered image \u2014 never claim a visual result.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "documents": {
     "description": "document ids (from the project map) and/or lib: addresses (from the catalogue or grep) to read; empty = the shader you are currently working on. NEVER means 'all'.",
     "items": {
      "type": "string"
     },
     "title": "Documents",
     "type": "array"
    }
   },
   "title": "_ReadShaderArgs",
   "type": "object"
  }
 },
 {
  "name": "render_image",
  "description": "Render the document's CURRENT frame to an image file (PNG) under the project's renders folder. The app pauses briefly while it encodes, and the user confirms first. Returns the actual (codec-snapped) size; the file itself becomes a 'Reveal render' button shown to the USER \u2014 you get NEITHER the path nor a look at the image. You render the live source \u2014 land your edits before rendering.",
  "parameters": {
   "$defs": {
    "RenderShape": {
     "enum": [
      "native",
      "short_720",
      "short_1080",
      "short_1440",
      "wide_720",
      "wide_1080",
      "wide_1440"
     ],
     "title": "RenderShape",
     "type": "string"
    }
   },
   "additionalProperties": false,
   "properties": {
    "document": {
     "default": "",
     "description": "document id (from the project map); empty = the shader you're working on",
     "title": "Document",
     "type": "string"
    },
    "shape": {
     "$ref": "#/$defs/RenderShape",
     "default": "native",
     "description": "output size: native (the document's canvas size, any aspect), short_720/short_1080/short_1440 (9:16 vertical), or wide_720/wide_1080/wide_1440 (16:9). Dims snap to the codec alignment."
    }
   },
   "title": "_RenderImageArgs",
   "type": "object"
  }
 },
 {
  "name": "render_video",
  "description": "Render `seconds` of the document's animation (always from t=0) to a video file (WebM) under the project's renders folder. The app pauses while it encodes; the user confirms first. Returns the actual size + duration; the file itself becomes a 'Reveal render' button shown to the USER \u2014 you get NEITHER the path nor a look at the video. You render the live source \u2014 land your edits before rendering. You cannot pick a start time other than 0.",
  "parameters": {
   "$defs": {
    "RenderShape": {
     "enum": [
      "native",
      "short_720",
      "short_1080",
      "short_1440",
      "wide_720",
      "wide_1080",
      "wide_1440"
     ],
     "title": "RenderShape",
     "type": "string"
    }
   },
   "additionalProperties": false,
   "properties": {
    "document": {
     "default": "",
     "description": "document id (from the project map); empty = the shader you're working on",
     "title": "Document",
     "type": "string"
    },
    "seconds": {
     "description": "how many seconds of the animation to render, from t=0 (required)",
     "exclusiveMinimum": 0.0,
     "maximum": 60.0,
     "title": "Seconds",
     "type": "number"
    },
    "fps": {
     "default": 30,
     "description": "frames per second",
     "maximum": 120,
     "minimum": 1,
     "title": "Fps",
     "type": "integer"
    },
    "shape": {
     "$ref": "#/$defs/RenderShape",
     "default": "native",
     "description": "output size: native (the document's canvas size, any aspect), short_720/short_1080/short_1440 (9:16 vertical), or wide_720/wide_1080/wide_1440 (16:9). Dims snap to the codec alignment."
    }
   },
   "required": [
    "seconds"
   ],
   "title": "_RenderVideoArgs",
   "type": "object"
  }
 },
 {
  "name": "set_uniform",
  "description": "Change a uniform's runtime VALUE \u2014 for tweaking a number/vector the user controls live (brightness, speed, a color), WITHOUT editing code. Read the document first so you know the uniform's type and current value. Only scalar and vector uniforms can be set; samplers, uniform blocks, and engine-driven uniforms (u_time, u_aspect, u_resolution) cannot. A SCRIPT-DRIVEN uniform also cannot be set \u2014 the document script (script.py) overwrites it every tick; change it in write_script instead. To change the shader's LOGIC, or to add/remove a uniform, edit the SOURCE instead. The value is in memory until the user saves the project; you cannot see the result \u2014 report the value you set, not how it looks.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "name": {
     "description": "the uniform's name (e.g. u_color)",
     "title": "Name",
     "type": "string"
    },
    "value": {
     "anyOf": [
      {
       "type": "number"
      },
      {
       "type": "integer"
      },
      {
       "type": "string"
      },
      {
       "items": {
        "anyOf": [
         {
          "type": "number"
         },
         {
          "type": "integer"
         }
        ]
       },
       "type": "array"
      }
     ],
     "description": "the value, shaped to the uniform: a NUMBER for a scalar; a LIST of numbers for a vector ([1.0, 0.0, 0.0] for a vec3) or a numeric array; a STRING for a uint text array (e.g. \"Hello\\nWorld\" for u_text \u2014 ShaderBox converts it to codepoints, the same control the user has in the UI). To change displayed TEXT, set the text uniform with a string \u2014 do NOT edit the source (a uniform can't be default-initialized).",
     "title": "Value"
    },
    "document": {
     "default": "",
     "description": "document id (from the project map); empty = the document you're working on",
     "title": "Document",
     "type": "string"
    }
   },
   "required": [
    "name",
    "value"
   ],
   "title": "_SetUniformArgs",
   "type": "object"
  }
 },
 {
  "name": "switch_document",
  "description": "Make a document the CURRENT shader (the one the user is viewing). The publish and render tools, and edits with no target, all act on the current shader \u2014 so to publish/render a DIFFERENT document, switch to it first. Pass the document id from the project map. Non-destructive: the user's view switches to it.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "document": {
     "description": "document id (from the project map) to make the current shader \u2014 REQUIRED",
     "title": "Document",
     "type": "string"
    }
   },
   "required": [
    "document"
   ],
   "title": "_SwitchDocumentArgs",
   "type": "object"
  }
 },
 {
  "name": "write_script",
  "description": "Create or replace a document's Python script: a `class Behavior(ScriptBehavior)` whose `update(self, ctx) -> dict` returns {uniform_name: value} to drive those uniforms every frame. For STATE the shader cannot hold \u2014 a value that depends on the PREVIOUS frame (`self.*` persists): an integrator, an accumulator, a phase machine, a score. A pure function of time belongs in the shader (u_time), not here. BEST FOR a fresh script or a full rewrite; for a localized change prefer edit_script. Send the COMPLETE script \u2014 I compile + motion-probe it and return the verdict.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "new_text": {
     "description": "the script's COMPLETE new source \u2014 this replaces the whole script.py (a `class Behavior(ScriptBehavior)` with `update(self, ctx) -> dict`). Anything omitted is gone.",
     "title": "New Text",
     "type": "string"
    },
    "document": {
     "default": "",
     "description": "document id (from the project map); empty = the document you are currently working on",
     "title": "Document",
     "type": "string"
    }
   },
   "required": [
    "new_text"
   ],
   "title": "_WriteScriptArgs",
   "type": "object"
  }
 },
 {
  "name": "write_shader",
  "description": "Replace a file's ENTIRE source with new_text, or create a new lib: file. BEST FOR a full-function rewrite or any broad change in a small-to-medium file (roughly <=150 lines: just rewrite it whole \u2014 the working set already shows the full source); for a small localized change prefer edit_shader. Send the COMPLETE file: anything you omit is deleted \u2014 the result notes any top-level function/declaration the rewrite removed, so check it. (One write_shader per file per step \u2014 see HOW TO WORK.) After the write I recompile and return any compile errors; if there are none, it compiled clean. You cannot see the rendered image \u2014 never claim a visual result.",
  "parameters": {
   "additionalProperties": false,
   "properties": {
    "new_text": {
     "description": "the file's COMPLETE new source \u2014 this replaces the whole file, anything omitted is gone",
     "title": "New Text",
     "type": "string"
    },
    "target": {
     "default": "",
     "description": "what to edit: empty = the shader you're currently working on; a document id (from the project map) = that document; a 'lib:<path>' address (from the library catalogue) = that library file \u2014 a 'lib:<path>' that doesn't exist yet is CREATED here (the way to add a new library file)",
     "title": "Target",
     "type": "string"
    }
   },
   "required": [
    "new_text"
   ],
   "title": "_WriteShaderArgs",
   "type": "object"
  }
 }
]

